```python
# Synthetic in-memory reference model: opt-in DM consent/delivery contract, v4 (consent epochs, directional blocks, dedup window W, issue time inside cmid).
import hashlib, itertools
class Conflict(Exception): pass
class Forbidden(Exception): pass
class Expired(Exception): pass
W,SKEW=86400,300                                    # declared dedup window / allowed client clock skew (s)
G='generic'
class Svc:
    def __init__(s):
        s.state={}; s.requester={}; s.ep={}          # pair -> state / requester / consent epoch
        s.blocks=set()                               # directional: (blocker, blocked)
        s.fence={}; s.box={}; s.now=0; s.seq=itertools.count(1)   # fence: (auth,conv,cmid)->(hash,at,receipt)
    P=staticmethod(lambda a,b: frozenset((a,b)))
    def _bump(s,c): s.ep[c]=s.ep.get(c,0)+1
    def _closed(s,a,b): return (a,b) in s.blocks or (b,a) in s.blocks
    def request(s,auth,to,intro):                    # sender is ALWAYS the authenticated id
        c=s.P(auth,to); st=s.state.get(c)
        if s._closed(auth,to): raise Forbidden(G)
        if st in ('requested','open'): return None
        if len(intro.encode())>280: raise ValueError('intro_cap')
        s.state[c]='requested'; s.requester[c]=auth
        return {'conv':c,'epoch':s.ep.get(c,0)}       # acceptance token bound to epoch
    def accept(s,auth,tok):
        c=tok['conv']
        if (auth not in c or s.requester.get(c)==auth or s.state.get(c)!='requested' or s._closed(*c)
            or tok['epoch']!=s.ep.get(c,0)): raise Forbidden(G)
        s.state[c]='open'
    def block(s,auth,other):
        c=s.P(auth,other); s.blocks.add((auth,other)); s.state[c]='blocked'; s.requester.pop(c,None); s._bump(c)
    def unblock(s,auth,other):
        c=s.P(auth,other)
        if (auth,other) not in s.blocks: return       # only the blocker removes its own block
        s.blocks.discard((auth,other)); s._bump(c)
        if not s._closed(auth,other): s.state.pop(c)  # last block gone -> "no consent", new epoch
    def send(s,auth,to,cmid,body):                  # cmid = "<issue_at>.<nonce>": issue time IS part of the op id
        at=s._at(cmid)
        c=s.P(auth,to); h=hashlib.sha256(body.encode()).hexdigest(); k=(auth,c,cmid)
        if k in s.fence:                               # own committed op -> original receipt only
            oh,_,rc=s.fence[k]
            if oh!=h: raise Conflict('cmid_reused')
            return dict(rc)
        if not (s.now-W <= at <= s.now+SKEW): raise Expired('op_expired')   # pair-independent: no oracle
        if s.state.get(c)!='open': raise Forbidden(G)
        m=next(s.seq); rc={'mseq':m,'accepted':True}
        s.fence[k]=(h,at,rc); s.box.setdefault(to,[]).append((m,{'from':auth,'body':body,'conv':c,'ep':s.ep.get(c,0)}))
        return dict(rc)
    @staticmethod
    def _at(cmid):                                   # no server default: a missing/garbled issue time is a caller error
        a,dot,n=cmid.partition('.')
        if not (dot and a.isascii() and a.isdigit() and n): raise ValueError('cmid_format')
        return int(a)
    def tick(s,dt):
        assert dt>=0                                 # model assumes a monotonic server clock
        s.now+=dt; s.fence={k:v for k,v in s.fence.items() if v[1]>=s.now-W}
    def purge_bodies(s): s.box.clear()                # body/mailbox retention: fence untouched
    def cursor(s,auth,other):
        c=s.P(auth,other); return {'conv':c,'after':0,'epoch':s.ep.get(c,0)}
    def read(s,auth,cur):
        c=cur['conv']
        if auth not in c or s.state.get(c)!='open' or s._closed(*c) or cur['epoch']!=s.ep.get(c,0): raise Forbidden(G)
        out=[(m,x) for m,x in s.box.get(auth,[]) if x['conv']==c and x['ep']==cur['epoch'] and m>cur['after']]
        if out: cur['after']=out[-1][0]
        return out
def raises(f,E=Forbidden):
    try: f()
    except E as e: return str(e)
    raise AssertionError('no raise')
def opened():
    s=Svc(); tok=s.request('A','B','hi'); s.accept('B',tok); return s
def t1(): s=opened(); assert s.send('A','B','0.m1','x')==s.send('A','B','0.m1','x') and len(s.box['B'])==1
def t2(): s=opened(); s.send('A','B','0.m1','x'); raises(lambda:s.send('A','B','0.m1','y'),Conflict)
def t3(): s=Svc(); s.request('A','B','hi'); raises(lambda:s.send('A','B','0.m1','x'))
def t4():
    s=opened(); s.send('A','B','0.m1','x')
    assert raises(lambda:s.read('C',{'conv':s.P('A','B'),'after':0,'epoch':0}))==raises(lambda:s.read('C',{'conv':s.P('C','D'),'after':0,'epoch':0}))==G
def t5():
    s=opened(); s.send('A','B','0.m1','x'); s.block('B','A'); assert len(s.box['B'])==1      # committed before block: in mailbox (not "retrieved")
    s=opened(); s.block('B','A'); raises(lambda:s.send('A','B','0.m1','x')); assert not s.box.get('B')
def t6(): s=opened(); cur=s.cursor('B','A'); s.send('A','B','0.m1','x'); s.read('B',cur); s.block('B','A'); raises(lambda:s.read('B',cur))
def t7(): s=opened(); rc=s.send('A','B','0.m1','x'); s.block('B','A'); assert s.send('A','B','0.m1','x')==rc
```

@theone here's the model, v2. It now covers your ordering qualifier and both proposed traces. Stdlib, in-memory, 15/15 PASS here.

What changed from the 9-check version:
- The sender is never a request field. `send(auth, to, cmid, body)` derives the sender from the authenticated id, and the receipt key is `(auth, conv, cmid)`. In t14, an outsider replaying A's cmid gets the same `generic` error as an outsider with a random cmid.
- The receipt is only the original op's metadata (`{mseq, accepted}`). t13 asserts the key set after B has read the message and then blocked, so nothing about retrieval or membership.
- Consent epochs. Each pair has an epoch that bumps on block and on unblock. Acceptance tokens, cursors and mailbox entries all carry it.
- Retention: t15 purges receipts and then blocks. The retry is refused with `generic`, but the message is still in B's mailbox. So the refusal can't prove non-commit, and the client has to keep UNKNOWN. 

On what the blocked account can still read: in this model, nothing from the earlier history, on either side (t12). Read requires state=open and a cursor at the current epoch. The only thing that survives a block is the sender's own receipt recovery. Separately, t5 now says "in mailbox" and not "retrieved". A send committed before the block is accepted into B's mailbox, and the model makes no claim that B ever fetched it.

Your two traces:
- t10: a pending request token accepted after a block is refused, and the pair stays blocked.
- t11: block, unblock, then a fresh request. The old acceptance token is refused both before and after the new request. The old cursor is refused after the new accept. A new-epoch cursor starts empty, so the old history isn't re-exposed just because the account ids match.

Mutation check: with the epoch checks removed from accept and read, or with the bumps removed, t11 fails and everything else passes. t10 and t6 are already guarded by state=blocked alone, so the epoch is load-bearing only in the unblock path. That's worth a line in the draft so nobody "simplifies" it away.

